## Design Note

- **Tokenizer → Token list → iterative state-machine parser** (explicit stack of continuation frames, no Python recursion) builds a **flat AST** (list of tuples, nodes referenced by index).
- **Evaluator** walks the AST with two explicit stacks (work + values); `if` is lazy by pushing only the chosen branch.
- **Compile-time checks** (unknown function name, arg count) are applied after parsing, scanning calls by source position (leftmost wins).
- **Concurrency**: AST is immutable post-compile; `evaluate` allocates thread-local stacks — no shared mutable state.
- Complexity: O(n) parse, O(n) per evaluation; memory O(n). All depths handled by list-based stacks.

### solution.py
```python
"""Safe formula engine for spreadsheet cells.

Design:
- Tokenizer → token list; iterative Pratt-style parser with explicit stack builds a flat AST (list of tuples).
- AST is immutable after compile; evaluation uses an explicit (work, value) stack → O(n) per eval, no recursion.
- Thread safety: AST read-only, evaluator uses thread-local stacks; no shared mutable state.
- Parsing depth = len(stack); no Python recursion for nesting.
- Number validation (finite), compile-time function name/arg-count checks; errors deferred to eval for names/arith.
"""
from __future__ import annotations

import math
from typing import Mapping

__all__ = [
    "ExprError",
    "ExprSyntaxError",
    "ExprNameError",
    "ExprEvalError",
    "Expr",
    "compile_expr",
    "evaluate",
]


# ─── Exceptions ────────────────────────────────────────────────────────────────

class ExprError(Exception):
    pass


class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.message = message
        self.position = position


class ExprNameError(ExprError):
    def __init__(self, name: str):
        super().__init__(f"Unknown name: {name!r}")
        self.name = name


class ExprEvalError(ExprError):
    pass


# ─── Constants ─────────────────────────────────────────────────────────────────

_CMP_OPS = frozenset("< <= > >= == !=".split())
_ADD_OPS = frozenset("+-")
_MUL_OPS = frozenset("*/%")

# function name → (min_args, max_args_or_None)
_FUNCS: dict[str, tuple[int, int | None]] = {
    "abs": (1, 1),
    "sqrt": (1, 1),
    "min": (1, None),
    "max": (1, None),
    "round": (1, 2),
    "if": (3, 3),
}


# ─── Tokenizer ─────────────────────────────────────────────────────────────────

def _tokenize(src: str) -> list[tuple[str, str, int]]:
    """Return list of (kind, value, pos). kind ∈ {num,ident,op,lparen,rparen,comma,invalid,badnum}."""
    tokens: list[tuple[str, str, int]] = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        # Whitespace
        if c in " \t\n\r":
            i += 1
            continue
        # Number
        if c.isdigit():
            start = i
            while i < n and src[i].isdigit():
                i += 1
            if i < n and src[i] == ".":
                i += 1
                while i < n and src[i].isdigit():
                    i += 1
            if i < n and src[i] in "eE":
                i += 1
                if i < n and src[i] in "+-":
                    i += 1
                if i < n and src[i].isdigit():
                    while i < n and src[i].isdigit():
                        i += 1
                else:
                    tokens.append(("badnum", src[start:i], start))
                    continue
            tokens.append(("num", src[start:i], start))
        elif c == ".":
            if i + 1 < n and src[i + 1].isdigit():
                start = i
                i += 1
                while i < n and src[i].isdigit():
                    i += 1
                if i < n and src[i] in "eE":
                    i += 1
                    if i < n and src[i] in "+-":
                        i += 1
                    if i < n and src[i].isdigit():
                        while i < n and src[i].isdigit():
                            i += 1
                    else:
                        tokens.append(("badnum", src[start:i], start))
                        continue
                tokens.append(("num", src[start:i], start))
            else:
                tokens.append(("invalid", ".", i))
                i += 1
        # Identifier
        elif c.isalpha() or c == "_":
            start = i
            i += 1
            while i < n and (src[i].isalnum() or src[i] == "_"):
                i += 1
            tokens.append(("ident", src[start:i], start))
        # Operators
        elif c == "+":
            tokens.append(("op", "+", i)); i += 1
        elif c == "-":
            tokens.append(("op", "-", i)); i += 1
        elif c == "*":
            tokens.append(("op", "*", i)); i += 1
        elif c == "/":
            tokens.append(("op", "/", i)); i += 1
        elif c == "%":
            tokens.append(("op", "%", i)); i += 1
        elif c == "^":
            tokens.append(("op", "^", i)); i += 1
        elif c == "<":
            if i + 1 < n and src[i + 1] == "=":
                tokens.append(("op", "<=", i)); i += 2
            else:
                tokens.append(("op", "<", i)); i += 1
        elif c == ">":
            if i + 1 < n and src[i + 1] == "=":
                tokens.append(("op", ">=", i)); i += 2
            else:
                tokens.append(("op", ">", i)); i += 1
        elif c == "=":
            if i + 1 < n and src[i + 1] == "=":
                tokens.append(("op", "==", i)); i += 2
            else:
                tokens.append(("invalid", "=", i)); i += 1
        elif c == "!":
            if i + 1 < n and src[i + 1] == "=":
                tokens.append(("op", "!=", i)); i += 2
            else:
                tokens.append(("invalid", "!", i)); i += 1
        elif c == "(":
            tokens.append(("lparen", "(", i)); i += 1
        elif c == ")":
            tokens.append(("rparen", ")", i)); i += 1
        elif c == ",":
            tokens.append(("comma", ",", i)); i += 1
        else:
            tokens.append(("invalid", c, i)); i += 1
    return tokens


